def find_components(grid):
    bg = 6
    visited = set()
    components = []

    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != bg and (r, c) not in visited:
                component = []
                stack = [(r, c)]
                while stack:
                    cr, cc = stack.pop()
                    if (cr, cc) in visited:
                        continue
                    visited.add((cr, cc))
                    comp_val = grid[cr][cc]
                    component.append(comp_val)
                    # Check neighbors
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                            if grid[nr][nc] != bg and (nr, nc) not in visited:
                                stack.append((nr, nc))
                # Pad to 2D shape
                rows = len([c for _, v in visited])
                cols = max(max(c for _, v in visited) for _, _ in visited) + 1 if visited else 0
                components.append(component)

    return components

